#include <iostream>
#include <type_traits>

template<typename T>
struct PointerType {
    using type = T;
};

// Specialization for null pointer constant
template<>
struct PointerType<std::nullptr_t> {
    using type = std::nullptr_t;
};

// Function to determine composite pointer type
template<typename P1, typename P2>
auto get_composite_pointer_type() {
    if constexpr (std::is_null_pointer_v<P1> && std::is_null_pointer_v<P2>) {
        return std::nullptr_t{};
    } else if constexpr (std::is_null_pointer_v<P1>) {
        return P2{};
    } else if constexpr (std::is_null_pointer_v<P2>) {
        return P1{};
    } else {
        return typename PointerType<P1>::type{}; // or other logic
    }
}

int main() {
    auto p1 = get_composite_pointer_type<int*, std::nullptr_t>();
    auto p2 = get_composite_pointer_type<std::nullptr_t, double*>();
    auto p3 = get_composite_pointer_type<std::nullptr_t, std::nullptr_t>();
    std::cout << "p1 is pointer type: " << std::is_pointer<decltype(p1)>::value << '\n';
    std::cout << "p2 is pointer type: " << std::is_pointer<decltype(p2)>::value << '\n';
    std::cout << "p3 is nullptr_t: " << std::is_same<decltype(p3), std::nullptr_t>::value << '\n';
    return 0;
}
